package com.bananalab.lite;
import android.app.*;
import android.content.*;
import android.widget.*;
import java.net.*;
import java.io.*;
import java.util.regex.*;
final class PageReader {
 static final int LIMIT=67108864;static File cache;
 static URL address(String input)throws IOException{
  URL url=new URL(input);
  if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||(url.getPort()!=-1&&url.getPort()!=443))throw new IOException("Usa una pagina publica HTTPS sin credenciales");
  String host=url.getHost();if(host.isEmpty()||host.equalsIgnoreCase("localhost")||host.endsWith(".local"))throw new IOException("Direccion local no admitida");
  for(InetAddress a:InetAddress.getAllByName(host))if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress()||(a.getAddress().length==16&&(a.getAddress()[0]&0xfe)==0xfc))throw new IOException("La pagina debe estar en Internet publico");
  return url;
 }
 static String clean(String html){
  String text=html.replaceAll("(?is)<!--.*?-->|<(head|script|style|noscript|svg|nav|footer|header|aside|form)\\b[^>]*>.*?</\\1\\s*>"," ").replaceAll("(?s)<[^>]*>"," ");
  text=text.replace("&nbsp;"," ").replace("&amp;","&").replace("&lt;","<").replace("&gt;",">").replace("&quot;","\"").replace("&#39;","'");
  Matcher entity=Pattern.compile("&#(x[0-9a-fA-F]+|[0-9]+);").matcher(text);StringBuffer decoded=new StringBuffer();
  while(entity.find()){String replacement=" ";try{String n=entity.group(1);int code=n.startsWith("x")?Integer.parseInt(n.substring(1),16):Integer.parseInt(n);if(Character.isValidCodePoint(code))replacement=new String(Character.toChars(code));}catch(Exception ignored){}entity.appendReplacement(decoded,Matcher.quoteReplacement(replacement));}entity.appendTail(decoded);
  return decoded.toString().replaceAll("\\s+"," ").trim();
 }
 static final class Document implements java.io.Closeable{final String title,text,url;final File file;java.util.List<String> links=new java.util.ArrayList<>();Document(String t,String x,String u){title=t;text=x;url=u;file=null;}Document(String t,File f,String u)throws Exception{title=t;file=f;url=u;StringBuilder preview=new StringBuilder();try(Reader in=NotebookDisk.reader(new FileInputStream(f))){char[] b=new char[4096];int n=in.read(b);if(n>0)preview.append(b,0,n);}text=preview.toString();}Reader reader()throws Exception{return file==null?new StringReader(text):NotebookDisk.reader(new FileInputStream(file));}public void close(){if(file!=null)file.delete();}}
 static Document fetch(Context c,String input)throws Exception{return fetch(input,c.getCacheDir());}
 static Document fetch(String input)throws Exception{return fetch(input,cache!=null?cache:new File(System.getProperty("java.io.tmpdir",".")));}
 static Document fetch(String input,File folder)throws Exception{PageStream.Budget budget=new PageStream.Budget();URL url=address(input.trim());if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("No pude preparar el espacio temporal");File raw=File.createTempFile("banana-http-",".part",folder);boolean htmlPage=true;String charset="UTF-8";try{boolean received=false;for(int redirect=0;redirect<4;redirect++){budget.check();HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","BananaLabLite/0.67 public-page-reader");c.setRequestProperty("Accept","text/html,text/plain");c.setRequestProperty("Accept-Encoding","identity");try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Redireccion sin destino");url=address(new URL(url,location).toString());continue;}if(status!=200)throw new IOException("La pagina respondio "+status);String type=c.getContentType(),mime=type==null?"":type.toLowerCase(java.util.Locale.ROOT);htmlPage=mime.startsWith("text/html");if(!(htmlPage||mime.startsWith("text/plain")))throw new IOException("Solo se leen paginas HTML o texto");if(c.getContentLength()>LIMIT)throw new IOException("La página supera64 MiB");Matcher encoding=Pattern.compile("charset\\s*=\\s*[\"']?([a-zA-Z0-9_-]+)",Pattern.CASE_INSENSITIVE).matcher(type);if(encoding.find())charset=encoding.group(1);try(InputStream body=new PageStream.Limited(c.getInputStream(),LIMIT);OutputStream out=new BufferedOutputStream(new FileOutputStream(raw))){InputStream decoded="gzip".equalsIgnoreCase(c.getContentEncoding())?new java.util.zip.GZIPInputStream(body):body;PageStream.copy(decoded,out,LIMIT,budget);}received=true;break;}finally{c.disconnect();}}if(!received)throw new IOException("Demasiadas redirecciones");Reader decoded=new InputStreamReader(new FileInputStream(raw),java.nio.charset.Charset.forName(charset).newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT));return PageStream.extract(folder,url.toString(),decoded,htmlPage,budget);}finally{raw.delete();}}
 static Document document(String url,String content,boolean htmlPage)throws Exception{String selected=content;if(htmlPage){Matcher main=Pattern.compile("(?is)<(main|article)\\b[^>]*>(.*?)</\\1\\s*>").matcher(content);String longest="";while(main.find())if(main.group(2).length()>longest.length())longest=main.group(2);if(!longest.isEmpty())selected=longest;}String text=htmlPage?clean(selected):selected.trim();if(text.length()<40)throw new IOException("No se encontro texto util; puede requerir JavaScript o acceso privado");String title=new URL(url).getHost();if(htmlPage){Matcher heading=Pattern.compile("(?is)<title[^>]*>(.*?)</title>").matcher(content);if(heading.find())title=clean(heading.group(1));}Document out=new Document(title,text,url);if(htmlPage){Matcher link=Pattern.compile("(?is)<a\\b[^>]*?\\bhref\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))").matcher(content);while(link.find()&&out.links.size()<PageCrawl.PAGE_LINKS)out.links.add(link.group(1)!=null?link.group(1):link.group(2)!=null?link.group(2):link.group(3));}return out;}
 static String failure(String url,Exception error){String host="el enlace";try{host=new java.net.URI(url).getHost();}catch(Exception ignored){}String reason="";for(Throwable e=error;e!=null;e=e.getCause()){if(e instanceof java.net.UnknownHostException){reason="No pude resolver el dominio (DNS). Revisá la conexión, el DNS o la VPN del dispositivo.";break;}if(e instanceof javax.net.ssl.SSLException){reason="Falló la conexión segura TLS/certificado. No desactivé la verificación de seguridad.";break;}if(e instanceof java.net.SocketTimeoutException){reason="La conexión o lectura agotó el tiempo de espera.";break;}if(e instanceof java.net.ConnectException){reason="No pude establecer conexión con el servidor.";break;}}
  if(reason.isEmpty()){String message=error.getMessage()==null?error.getClass().getSimpleName():error.getMessage();Matcher status=Pattern.compile("(?:HTTP|respondio) ([0-9]{3})").matcher(message);if(status.find()){int code=Integer.parseInt(status.group(1));reason="El servidor respondió HTTP "+code+". "+(code==401||code==403?"Puede requerir una sesión o bloquear lectores automatizados; que abra en el navegador no asegura acceso desde este lector.":code==429?"El sitio limita las peticiones; probá más tarde.":code==404?"La página no existe en esa dirección.":"El servidor no entregó el contenido solicitado.");}else if(message.contains("texto util"))reason="El HTML recibido no contenía suficiente texto útil. Puede depender de JavaScript o de una sesión del navegador.";else reason=message;}
  return "No pude leer directamente "+host+".\n"+reason+"\nNo usé el buscador general ni guardé contenido nuevo con este intento. Si podés copiar el texto visible, pegalo con «Aprendé esto: …».";
 }
 static String read(Context context,String input,String topic)throws Exception{try(Document d=fetch(context,input)){String receipt=KnowledgeNotebook.rememberReader(context,d.title,d.reader(),d.url,"web");try{WebMemory.rememberExternal(context,topic,d.title,d.text.substring(0,Math.min(4000,d.text.length())),d.url);Knowledge.learn(topic,d.text);}catch(Exception legacy){return receipt+"\nEl documento quedó guardado; no pude actualizar la memoria web antigua.";}return receipt;}}



 static void show(final Activity activity){
  LinearLayout layout=new LinearLayout(activity);layout.setOrientation(1);layout.setPadding(24,12,24,12);
  EditText topic=new EditText(activity);topic.setHint("Tema: por ejemplo, ajolote");layout.addView(topic);
  EditText url=new EditText(activity);url.setHint("https://pagina-publica...");url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);layout.addView(url);
  TextView note=new TextView(activity);note.setText("Lee una pagina publica por vez. Indexa términos y definiciones para responder con texto y fuente; no cambia los pesos neuronales. No ejecuta instrucciones de la pagina ni scripts.");layout.addView(note);
  Button read=new Button(activity);read.setText("Leer y guardar en este Android");layout.addView(read);Button cancel=new Button(activity);cancel.setText("Cancelar lectura");cancel.setEnabled(false);layout.addView(cancel);
  final Thread[] worker=new Thread[1];final boolean[] closed={false};
  AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Paginas y conocimiento").setView(layout).setPositiveButton("Cerrar",null).create();
  cancel.setOnClickListener(v->{if(worker[0]!=null)worker[0].interrupt();note.setText("Cancelando…");});
  dialog.setOnDismissListener(d->{closed[0]=true;if(worker[0]!=null)worker[0].interrupt();});
  read.setOnClickListener(v->{final String name=Knowledge.normalize(topic.getText().toString()).trim(),link=url.getText().toString();if(!name.matches("[a-z][a-z ]{1,49}")){note.setText("Escribi un tema de entre 2 y 50 letras");return;}read.setEnabled(false);cancel.setEnabled(true);note.setText("Leyendo pagina…");worker[0]=new Thread(()->{String message;try{message=read(activity.getApplicationContext(),link,name);}catch(Exception e){message="No pude leerla: "+e.getMessage();}final String result=message;activity.runOnUiThread(()->{if(!closed[0]&&!activity.isFinishing()){note.setText(result);read.setEnabled(true);cancel.setEnabled(false);}});},"banana-page-reader");worker[0].start();});UiTypeface.show(dialog);
 }
}
